<script setup lang="ts">
import {ref, onMounted} from 'vue'
type Route={id:string;domain:string;port:number;scheme:string;upstream:string;certificate_id:string;enabled:boolean}
type Cert={id:string;domains:string[];mode:string;email:string;provider:string;token_env:string;staging:boolean}
type DDNS={id:string;provider:string;zone_id:string;record_id:string;name:string;type:string;ip:string;token_env:string;interval_seconds:number;enabled:boolean}
type Config={revision:number;routes:Route[];certificates:Cert[];ddns:DDNS[]}
const token=ref(''),logged=ref(false),busy=ref(false),message=ref(''),tab=ref('routes'),status=ref<{proxy?:{running:boolean;modules?:string[]};ddns?:Record<string,{ok:boolean;message:string;ip:string;at:string}>}>({})
const config=ref<Config>({revision:0,routes:[],certificates:[],ddns:[]})
const route=ref<Route>(newRoute()),cert=ref<Cert>(newCert()),dns=ref<DDNS>(newDNS()),domains=ref(''),editing=ref(false)
function logout(){logged.value=false;token.value='';sessionStorage.removeItem('netlite-token')}
function id(){return Array.from(crypto.getRandomValues(new Uint8Array(8)),b=>b.toString(16).padStart(2,'0')).join('')}
function newRoute():Route{return {id:id(),domain:'',port:18080,scheme:'http',upstream:'http://127.0.0.1:8080',certificate_id:'',enabled:true}}
function newCert():Cert{return {id:id(),domains:[],mode:'internal',email:'',provider:'cloudflare',token_env:'NETLITE_CF_TOKEN',staging:true}}
function newDNS():DDNS{return {id:id(),provider:'cloudflare',zone_id:'',record_id:'',name:'',type:'A',ip:'',token_env:'NETLITE_CF_TOKEN',interval_seconds:300,enabled:false}}
async function api<T>(url:string,method='GET',body?:unknown):Promise<T>{const r=await fetch('/api'+url,{method,headers:{Authorization:'Bearer '+token.value,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const result=await r.json();if(!r.ok)throw new Error(result.error||r.statusText);return result}
async function action(fn:()=>Promise<void>){busy.value=true;message.value='';try{await fn()}catch(e){message.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function refresh(){status.value=await api('/status')}
async function login(){await action(async()=>{config.value=await api('/config');logged.value=true;sessionStorage.setItem('netlite-token',token.value);await refresh()})}
async function save(){config.value=await api('/config','PUT',config.value);message.value='配置已保存。反代与证书需点击「应用到代理」生效；已启用 DDNS 会自动运行。'}
function editRoute(x:Route){route.value={...x};editing.value=true}
function editCert(x:Cert){cert.value={...x,domains:[...x.domains]};domains.value=x.domains.join(', ');editing.value=true}
function editDNS(x:DDNS){dns.value={...x};editing.value=true}
function upsert<T extends {id:string}>(list:T[],x:T){const i=list.findIndex(a=>a.id===x.id);if(i<0)list.push(x);else list[i]=x}
async function submitRoute(){await action(async()=>{const old=JSON.parse(JSON.stringify(config.value));upsert(config.value.routes,{...route.value});try{await save();route.value=newRoute();editing.value=false}catch(e){config.value=old;throw e}})}
async function submitCert(){await action(async()=>{const old=JSON.parse(JSON.stringify(config.value));upsert(config.value.certificates,{...cert.value,domains:domains.value.split(/[,\s]+/).filter(Boolean)});try{await save();cert.value=newCert();domains.value='';editing.value=false}catch(e){config.value=old;throw e}})}
async function submitDNS(){await action(async()=>{const old=JSON.parse(JSON.stringify(config.value));upsert(config.value.ddns,{...dns.value});try{await save();dns.value=newDNS();editing.value=false}catch(e){config.value=old;throw e}})}
async function remove(kind:'routes'|'certificates'|'ddns',key:string){await action(async()=>{const old=JSON.parse(JSON.stringify(config.value));config.value[kind]=config.value[kind].filter(x=>x.id!==key) as Route[]&Cert[]&DDNS[];try{await save()}catch(e){config.value=old;throw e}})}
onMounted(()=>{token.value=sessionStorage.getItem('netlite-token')||'';if(token.value)login()})
</script>
<template>
 <main><header><div class="brand"><span class="logo">N</span><div><h1>NetLite</h1><p>让网络管理轻一点</p></div></div><span class="badge">0.1 · 本地管理</span></header>
 <section v-if="!logged" class="login card"><h2>进入管理面板</h2><p>输入应用私有数据目录中 admin-token 文件的管理令牌。</p><form @submit.prevent="login"><label>管理令牌<input v-model="token" type="password" autocomplete="current-password" required></label><button :disabled="busy">登录</button></form></section>
 <template v-else>
 <div class="toolbar"><span :class="['dot',status.proxy?.running?'on':'']"></span><span>Caddy {{status.proxy?.running?'运行中':'未运行'}}</span><span class="muted">配置版本 {{config.revision}}</span><button class="secondary" :disabled="busy" @click="action(refresh)">刷新状态</button><button class="secondary" :disabled="busy" @click="action(async()=>{await api('/proxy/validate','POST');message='配置校验通过'})">校验配置</button><button :disabled="busy" @click="action(async()=>{const r=await api<{applied_revision:number}>('/proxy/apply','POST');message='已应用版本 '+r.applied_revision+'；证书签发与续期由 Caddy 异步执行';await refresh()})">应用到代理</button></div>
 <nav><button v-for="[key,title] in [['routes','反向代理'],['certificates','HTTPS 证书'],['ddns','动态 DNS']]" :class="{active:tab===key}" @click="tab=key!;editing=false">{{title}}</button><button class="logout" @click="logout">退出</button></nav>
 <div v-if="tab==='routes'" class="grid"><section class="card"><h2>代理规则</h2><p class="muted">按域名和端口访问内网服务，支持 WebSocket。</p><p v-if="!config.routes.length" class="empty">还没有规则，从右侧添加第一个服务。</p><article v-for="r in config.routes" :key="r.id"><div><strong>{{r.scheme}}://{{r.domain}}:{{r.port}}</strong><p>{{r.upstream}} · {{r.enabled?'启用':'停用'}}</p></div><div class="small-actions"><button class="secondary" @click="editRoute(r)">编辑</button><button class="danger" :disabled="busy" @click="remove('routes',r.id)">删除</button></div></article></section>
 <section class="card"><h2>{{editing?'编辑':'添加'}}代理</h2><form @submit.prevent="submitRoute"><label>域名<input v-model="route.domain" placeholder="app.example.com" required></label><div class="fields"><label>协议<select v-model="route.scheme"><option>http</option><option>https</option></select></label><label>监听端口<input v-model.number="route.port" type="number" min="1024" max="65535" required></label></div><label>上游服务<input v-model="route.upstream" required></label><label v-if="route.scheme==='https'">证书策略<select v-model="route.certificate_id" required><option value="">请选择覆盖该域名的证书</option><option v-for="c in config.certificates" :value="c.id">{{c.domains.join(', ')}}</option></select></label><label class="check"><input v-model="route.enabled" type="checkbox">启用规则</label><button :disabled="busy">保存规则</button></form></section></div>
 <div v-if="tab==='certificates'" class="grid"><section class="card"><h2>证书策略</h2><p class="muted">Caddy 自动签发和续期。DNS-01 泛域名需要对应插件和凭据。</p><article v-for="c in config.certificates" :key="c.id"><div><strong>{{c.domains.join(', ')}}</strong><p>{{c.mode}} {{c.mode!=='internal'?(c.staging?'· 测试 CA':'· 正式 CA'):''}}</p></div><div class="small-actions"><button class="secondary" @click="editCert(c)">编辑</button><button class="danger" :disabled="busy" @click="remove('certificates',c.id)">删除</button></div></article><aside>应用成功仅表示配置生效。签发失败和续期信息见应用数据目录 caddy.log。内部证书需客户端自行信任。</aside></section>
 <section class="card"><h2>{{editing?'编辑':'添加'}}证书策略</h2><form @submit.prevent="submitCert"><label>域名（逗号分隔）<input v-model="domains" placeholder="*.example.com, example.com" required></label><label>签发方式<select v-model="cert.mode"><option value="internal">内部 CA（本地测试）</option><option value="acme">ACME（HTTP / TLS-ALPN）</option><option value="dns">DNS-01（Cloudflare 插件）</option></select></label><label v-if="cert.mode!=='internal'">联系邮箱<input v-model="cert.email" type="email"></label><label v-if="cert.mode==='dns'">令牌环境变量名<input v-model="cert.token_env" required></label><label v-if="cert.mode!=='internal'" class="check"><input v-model="cert.staging" type="checkbox">使用 Let's Encrypt 测试 CA</label><p class="muted">ACME 端口验证需公网 80/443 映射到应用端口。DNS-01 无需开放验证端口。</p><button :disabled="busy">保存策略</button></form></section></div>
 <div v-if="tab==='ddns'" class="grid"><section class="card"><h2>动态 DNS</h2><p class="muted">Cloudflare A / AAAA 记录定时同步，保留现有 TTL 和代理开关。</p><article v-for="d in config.ddns" :key="d.id"><div><strong>{{d.name}} · {{d.type}}</strong><p>{{d.enabled?'启用':'停用'}} · 每 {{d.interval_seconds}} 秒</p><p v-if="status.ddns?.[d.id]">{{status.ddns[d.id]?.ok?'✓':'!'}} {{status.ddns[d.id]?.message}} {{status.ddns[d.id]?.ip}}</p></div><div class="small-actions"><button class="secondary" @click="editDNS(d)">编辑</button><button class="secondary" :disabled="busy||!d.enabled" @click="action(async()=>{await api('/ddns/'+d.id+'/run','POST');await refresh();message='DDNS 已执行，请查看结果'})">立即同步</button><button class="danger" :disabled="busy" @click="remove('ddns',d.id)">删除</button></div></article></section>
 <section class="card"><h2>{{editing?'编辑':'添加'}} DDNS</h2><form @submit.prevent="submitDNS"><label>记录域名<input v-model="dns.name" required></label><div class="fields"><label>记录类型<select v-model="dns.type"><option>A</option><option>AAAA</option></select></label><label>更新间隔（秒）<input v-model.number="dns.interval_seconds" type="number" min="60" max="86400" required></label></div><label>Zone ID<input v-model="dns.zone_id" required></label><label>Record ID<input v-model="dns.record_id" required></label><label>令牌环境变量名<input v-model="dns.token_env" required></label><label>指定 IP（留空自动发现）<input v-model="dns.ip" placeholder="自动发现 IPv4 / IPv6 公网地址"></label><label class="check"><input v-model="dns.enabled" type="checkbox">保存后启用自动更新</label><p class="muted">凭据在启动环境中配置；界面不存储 API 密钥。</p><button :disabled="busy">保存 DDNS</button></form></section></div>
 </template><div v-if="message" class="message" role="status">{{message}}</div><footer>独立代理进程 · SQLite 配置 · 不接管系统 Web 服务</footer></main>
</template>
